"""Curated bilingual algorithm lessons; references are primary specifications and papers."""
from html import escape
from learning_diagrams import diagram
SOURCES={
 'nist':('NIST · PQC standardization','https://csrc.nist.gov/projects/post-quantum-cryptography/post-quantum-cryptography-standardization'),
 '203':('FIPS 203 · ML-KEM','https://csrc.nist.gov/pubs/fips/203/final'),
 '204':('FIPS 204 · ML-DSA','https://csrc.nist.gov/pubs/fips/204/final'),
 '205':('FIPS 205 · SLH-DSA','https://csrc.nist.gov/pubs/fips/205/final'),
 '208':('SP 800-208 · LMS / XMSS','https://csrc.nist.gov/pubs/sp/800/208/final'),
 'falcon':('Falcon · specification','https://falcon-sign.info/falcon.pdf'),
 'fn':('NIST · FN-DSA / FIPS 206','https://csrc.nist.gov/presentations/2025/fips-206-fn-dsa-falcon'),
 'hqc':('HQC · 2026-10-12 specification','https://pqc-hqc.org/doc/hqc_specifications_2026_10_12.pdf'),
 'hqc-nist':('NIST · HQC selection','https://www.nist.gov/news-events/news/2025/03/nist-selects-hqc-fifth-algorithm-post-quantum-encryption'),
 '8391':('RFC 8391 · XMSS','https://www.rfc-editor.org/rfc/rfc8391'),
 '8554':('RFC 8554 · LMS / HSS','https://www.rfc-editor.org/rfc/rfc8554'),
 'shor':('Shor · original paper','https://arxiv.org/abs/quant-ph/9508027'),
 'grover':('Grover · original paper','https://arxiv.org/abs/quant-ph/9605043'),
 'search':('Boyer et al. · tight bounds on quantum searching','https://arxiv.org/abs/quant-ph/9605034'),
}
def translator(lang):return lambda en,zh:zh if lang=='zh' else en
def p(*items):return ''.join('<p>'+escape(s)+'</p>' for s in items)
def math(text):return '<div class="algorithm-math"><code>'+escape(text)+'</code></div>'
def refs(lang,*ids):
    t=translator(lang)
    return '<p class="algorithm-references">'+t('Primary sources: ','一手资料：')+' · '.join(f'<a href="{SOURCES[i][1]}" target="_blank" rel="noopener noreferrer">{SOURCES[i][0]} ↗</a>' for i in ids)+'</p>'
def table(head,rows):return '<div class="algorithm-table-wrap" tabindex="0"><table class="algorithm-table"><thead><tr>'+''.join('<th scope="col">'+s+'</th>' for s in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+cell+('</th>' if i==0 else '</td>') for i,cell in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def section(lang,ident,number,title,body):
    return f'<section class="guide-section algorithm-section" id="{ident}"><div class="guide-heading"><span>{number} / ALGORITHM FIELD NOTES</span><h2>{title}</h2></div>{body}</section>'
def summary_rows(lang,linked=True):
    t=translator(lang)
    rows=[('ml-kem','ML-KEM / Kyber','KEM',t('Module lattice','模格'),'FIPS 203 · 2024',t('Noisy polynomial equations; re-encryption check','带噪声多项式方程；重加密校验')),
    ('ml-dsa','ML-DSA / Dilithium',t('Signature','签名'),t('Module lattice','模格'),'FIPS 204 · 2024',t('Fiat–Shamir with aborts; hints and norm bounds','带拒绝采样的 Fiat–Shamir；hint 与范数边界')),
    ('slh-dsa','SLH-DSA / SPHINCS+',t('Signature','签名'),t('Stateless hash-based','无状态哈希'),'FIPS 205 · 2024',t('FORS + WOTS+ + hypertree; larger signatures','FORS + WOTS+ + 超树；签名较大')),
    ('fn-dsa','FN-DSA / Falcon',t('Signature','签名'),'NTRU '+t('lattice','格'),t('FIPS 206 in development','FIPS 206 制定中'),t('Compact signatures; trapdoor Gaussian sampling','签名紧凑；陷门高斯采样实现复杂')),
    ('hqc','HQC','KEM',t('Code-based','纠错码'),t('Selected by NIST · 2025; standardization ongoing','NIST 于 2025 年选中；标准化进行中'),t('QC decoding; a non-lattice KEM alternative','准循环解码；补充非格基 KEM 路线')),
    ('stateful','LMS / XMSS',t('Signature','签名'),t('Stateful hash-based','有状态哈希'),'SP 800-208 · 2020',t('One-time keys + Merkle authentication; strict state control','一次性密钥 + Merkle 认证；严格管理状态'))]
    result=[]
    for ident,name,*cols in rows:
        result.append(([f'<a href="#{ident}">{name}</a>'] if linked else [name])+cols)
    return result

def pqc_body(lang):
    t=translator(lang);out=[]
    body=p(t('PQC is a set of classical cryptographic constructions intended to resist known classical and quantum attacks. It is not one algorithm, and it does not require a quantum computer. Read each family through four questions: what problem does it solve, what makes forgery or key recovery hard, how does the legitimate computation work, and what must an implementation preserve?','PQC 是一组运行在经典计算机上、旨在抵抗已知经典与量子攻击的密码构造，并非单个算法，也不需要量子计算机。阅读每条路线时回答四个问题：解决什么用途、攻击者面对什么困难、合法方如何计算、实现必须保留哪些条件？'))
    body+=diagram(lang,'pqc-map')
    body+=table([t('Algorithm','算法'),t('Task','用途'),t('Family','技术路线'),t('Standard status · checked 5 Nov 2026','标准状态 · 2026-11-05 核对'),t('Mechanism / trade-off','机制与取舍')],summary_rows(lang))
    body+=p(t('The names “Kyber”, “Dilithium” and “SPHINCS+” identify the source designs; standardized ML-KEM, ML-DSA and SLH-DSA have specific interfaces, encodings and domain separation. Submission-version software is not automatically FIPS-conformant. Likewise, a Falcon implementation must not be relabeled as a finalized FN-DSA implementation. HQC project specifications are not a published NIST FIPS.','Kyber、Dilithium 和 SPHINCS+ 是来源设计名称；标准化后的 ML-KEM、ML-DSA、SLH-DSA 规定了明确接口、编码与域分离，提交版软件不自动符合 FIPS。Falcon 实现也不能直接标为已定稿的 FN-DSA 实现。HQC 项目规范同样不等于已发布的 NIST FIPS。'))+refs(lang,'nist','208','hqc')
    out.append(section(lang,'landscape','01',t('Six entries, several security assumptions','六类算法，多种安全假设'),body))

    body=p(t('ML-KEM uses arithmetic in Rq = Zq[X]/(X²⁵⁶+1), with q=3329. Vectors of ring elements form a module. A public matrix A is expanded from a seed; small secret and error vectors produce t=As+e. Recovering s from these noisy public relations is related to Module-LWE. The module rank and noise/compression parameters vary with the parameter set. NTT accelerates polynomial multiplication; it is an implementation tool, not the security assumption.','ML-KEM 在 Rq = Zq[X]/(X²⁵⁶+1)、q=3329 上运算，多项式向量组成模。公开矩阵 A 由种子展开，小秘密和误差向量形成 t=As+e。由这些公开带噪关系恢复 s 与 Module-LWE 困难问题相关。不同参数组改变模秩及噪声、压缩参数。NTT 用于加速多项式乘法，本身不是安全假设。'))
    body+=diagram(lang,'mlkem-flow')+math('Teaching view of the internal PKE:\nt = As + e\nu = Aᵀr + e₁\nv = tᵀr + e₂ + Encode(m)\nv − sᵀu = Encode(m) + eᵀr + e₂ − sᵀe₁  (mod q)')
    body+=p(t('The large shared term cancels, leaving the encoded message plus bounded noise. Rounding recovers m when the specified error bounds hold. The equation omits the exact NTT representation, compression and serialization; it is not a replacement implementation. The internal K-PKE is not exposed as an approved standalone encryption service.','较大的公共项相消，剩下编码消息和受控噪声；在规定误差界内，舍入可恢复 m。上式省略精确 NTT 表示、压缩及序列化，不能直接当实现。内部 K-PKE 也不是可独立暴露的获批加密服务。'),t('Encapsulation samples a fresh 32-byte internal message m, derives a candidate shared secret and encryption coins from m and the encapsulation-key hash, then encrypts m. Decapsulation decrypts m′, derives the same quantities, re-encrypts and compares c′ with c. A correctly encoded ciphertext that fails this comparison selects the specified secret-derived fallback key by implicit rejection. Key/ciphertext length and format checks still apply; rejection behavior must not leak secret-dependent information.','封装选取新鲜的 32 字节内部随机消息 m，结合公钥哈希导出候选共享秘密与加密随机性，再加密 m。解封恢复 m′、重新导出这些量、重加密并比较 c′ 与 c。编码合法但比较失败的密文通过隐式拒绝选择规范规定的秘密派生回退密钥；密钥、密文长度与格式仍须检查，拒绝行为不能泄漏秘密相关信息。'),t('ML-KEM-512/768/1024 all output a 32-byte shared secret. The suffix is not its length. Authentication and transcript-bound key derivation belong to the protocol: an unauthenticated public-key substitution is not solved by the KEM alone.','ML-KEM-512/768/1024 都输出 32 字节共享秘密，名称后缀不是共享秘密长度。认证及绑定握手上下文的密钥派生由协议负责；KEM 自身不能防止未认证公钥被替换。'))+refs(lang,'203')
    out.append(section(lang,'ml-kem','02',t('ML-KEM: cancel a structured mask, then validate the ciphertext','ML-KEM：消去结构化掩码，再校验密文'),body))

    body=p(t('ML-DSA works over degree-256 polynomial rings with q=8380417. It combines Module-LWE-related hiding with short-relation hardness in a Fiat–Shamir signature construction. The secret contains small vectors s₁,s₂; the public relation is t=As₁+s₂. A signing mask y creates a commitment w=Ay. The message representative μ includes the appropriate public-key/message context.','ML-DSA 使用次数为 256、q=8380417 的多项式环，在 Fiat–Shamir 签名中结合 Module-LWE 相关隐藏性与短关系困难性。秘密包含小向量 s₁、s₂，公开关系为 t=As₁+s₂。签名掩码 y 产生承诺 w=Ay；消息代表值 μ 包含规定的公钥与消息上下文。'))
    body+=diagram(lang,'mldsa-flow')+math('Unrounded teaching relation:\nc ← challenge(μ, HighBits(Ay))\nz = y + c·s₁\nAz − c·t = Ay − c·s₂\nActual public key: t₁ = rounded high bits of t; signature includes hints.')
    body+=p(t('Hashing μ and HighBits(w), then applying SampleInBall, produces a sparse polynomial challenge c that binds the commitment to the message. The response z allows a verifier to reconstruct the required high bits without knowing y or the secret. The actual scheme transmits rounded t₁, so bounded hints repair the high-bit information lost through rounding. Verification checks challenge consistency, response norms, hint weight and valid encodings; checking just one algebraic equation is insufficient.','对 μ 和 HighBits(w) 哈希后，经 SampleInBall 得到稀疏多项式挑战 c，将承诺与消息绑定；响应 z 让验证方无需知道 y 或秘密即可重建所需高位。实际公钥传输舍入后的 t₁，因此还要用有界 hint 修正舍入丢失的高位信息。验证须检查挑战一致性、响应范数、hint 重量及编码，不能只检查一个代数等式。'),t('Signing rejects attempts with unsuitable bounds and samples another mask. This protects the output distribution from revealing the secret and keeps verification correct. Removing the rejection conditions to improve speed changes the scheme. FIPS 204 supports hedged and deterministic signing variants; both still require correct mask derivation and domain separation.','签名会拒绝边界不合适的尝试并重新取掩码，以防输出分布泄漏秘密并保证验证正确。为加速而删去拒绝条件会改变方案。FIPS 204 支持对冲随机与确定性签名变体，但二者都必须正确派生掩码并执行域分离。'),t('Parameter sets are ML-DSA-44, -65 and -87, named after matrix dimensions, not signature bit lengths. Pure ML-DSA and HashML-DSA are distinct standardized interfaces; an application cannot substitute an arbitrary prehash. Audit arithmetic, rejection loops, randomness, faults and side-channel behavior separately.','ML-DSA-44、65、87 依据矩阵维度命名，不是签名位数。Pure ML-DSA 与 HashML-DSA 是不同标准接口，不能随意替换为自定义预哈希。应分别审查算术、拒绝循环、随机数、故障及侧信道行为。'))+refs(lang,'204')
    out.append(section(lang,'ml-dsa','03',t('ML-DSA: a challenge, a masked response and carefully chosen aborts','ML-DSA：挑战、掩码响应与有条件的中止'),body))

    body=p(t('SLH-DSA relies on hash-based constructions rather than lattice equations. Its public key contains a public seed and a top-level Merkle root; secret seeds derive the many underlying signing secrets. Each signature starts with a message-dependent randomization value R and a digest that selects FORS leaves and a position in a large hypertree.','SLH-DSA 依赖哈希构造，而非格方程。公钥包含公开种子和顶层 Merkle 根，秘密种子派生底层大量签名秘密。每次签名先计算消息相关随机化值 R，再由摘要选择 FORS 叶和大型超树中的位置。'))
    body+=diagram(lang,'slh-flow')
    body+=p(t('FORS signs digest bits using a forest of small trees: selected secret values and authentication paths allow the verifier to reconstruct its roots and then a FORS public key. A WOTS+ signature authenticates that public key. Its Merkle path reaches a subtree root, which another WOTS+ key authenticates at the next layer. Repeating this process connects the message to the public top root.','FORS 用多个小树组成的森林签署摘要比特：选中的秘密值和认证路径使验证方恢复各树根，再得到 FORS 公钥。WOTS+ 签名认证这个公钥，Merkle 路径通向子树根；上一层 WOTS+ 再认证该根。逐层重复，将消息连接到公开顶层根。'),t('A signature therefore carries R, the FORS material and a sequence of WOTS+ signatures/Merkle paths. Verification rebuilds the public root; it does not decrypt a message. SHA2 and SHAKE variants, security levels and the “s”/“f” trade-off change sizes and speed. “s” prioritizes smaller signatures; “f” prioritizes faster operations.','因此签名携带 R、FORS 材料，以及一串 WOTS+ 签名和 Merkle 路径。验证通过重建公开根完成，并非解密消息。SHA2/SHAKE 变体、安全级别及 s/f 取舍改变尺寸与速度：s 优先较小签名，f 优先较快操作。'),t('Stateless means the signer does not maintain an incrementing leaf-use counter across calls. The complete construction makes unsafe reuse sufficiently unlikely within its security limits; it does not permit arbitrary reuse of a bare WOTS+ key. Implementations still need correct seeds, addresses/domain separation, parameter limits and protection against faults and leakage.','无状态是指调用间无需维护递增的已用叶计数器。完整构造使安全限制内的不安全复用概率足够小，不表示裸 WOTS+ 密钥可以任意复用。实现仍须正确处理种子、地址与域分离、参数限制，并防护故障及泄漏。'))+refs(lang,'205')
    out.append(section(lang,'slh-dsa','04',t('SLH-DSA: hash chains, a forest and an authenticated hypertree','SLH-DSA：哈希链、森林与被认证的超树'),body))

    body=p(t('Falcon is a hash-and-sign construction over NTRU lattices. Secret short polynomials f,g,F,G satisfy fG−gF=q, and h=g/f mod q is public. These secrets provide an efficient lattice trapdoor. The original Falcon parameters use q=12289 and n=512 or 1024; they should not be read as a finalized FN-DSA API or encoding.','Falcon 是 NTRU 格上的 hash-and-sign 构造。秘密短多项式 f、g、F、G 满足 fG−gF=q，公开 h=g/f mod q，这些秘密提供有效的格陷门。原始 Falcon 使用 q=12289、n=512 或 1024；这些参数不能代替尚未定稿的 FN-DSA 接口和编码。'))
    body+=diagram(lang,'falcon-flow')+math('c = HashToPoint(salt, M)\nFind short (s₁,s₂) with s₁ + s₂h ≡ c (mod q).\nVerifier reconstructs s₁ = c − s₂h and checks ||(s₁,s₂)||² ≤ bound.')
    body+=p(t('Many long vectors satisfy the public equation; producing a suitably short one is the hard part. The trapdoor lets the signer sample a short preimage from the required discrete Gaussian distribution using fast Fourier sampling. The wire signature encodes the salt and compressed s₂, not both full polynomials. Verification is largely public polynomial arithmetic and a norm check.','满足公开等式的长向量很多，难点是生成足够短的向量。签名方凭陷门，通过快速傅里叶采样从规定离散高斯分布中采样短原像。实际签名编码盐值和压缩后的 s₂，不是传输两条完整多项式。验证主要进行公开多项式算术及范数检查。'),t('Its compact signatures come with a demanding signing implementation: Gaussian sampling, FFT precision, encoding/rejection and timing behavior all matter. A mathematically correct sampler that leaks secret-dependent information is not a secure implementation. Contrast ML-DSA’s masked challenge/response with Falcon’s trapdoor preimage sampling; they are different lattice-signature designs.','紧凑签名伴随更高的签名实现要求：高斯采样、FFT 精度、编码/拒绝及时间行为都重要。数学正确但泄漏秘密相关信息的采样器仍不安全。ML-DSA 的掩码挑战/响应与 Falcon 的陷门原像采样是不同格签名设计。'),t('Status checked 5 November 2026: NIST still lists FIPS 206 as in development. Learn Falcon’s structure from its submission specification, and follow NIST for FN-DSA naming, final parameters and conformance requirements.','2026 年 11 月 5 日核对：NIST 仍将 FIPS 206 列为制定中。可用 Falcon 提交规范学习结构；FN-DSA 的名称、最终参数及符合性要求应跟踪 NIST。'))+refs(lang,'falcon','fn','nist')
    out.append(section(lang,'fn-dsa','05',t('FN-DSA / Falcon: compact signatures through a lattice trapdoor','FN-DSA / Falcon：用格陷门得到紧凑签名'),body))

    body=p(t('HQC is a code-based KEM built around quasi-cyclic decoding problems. Work in the binary cyclic ring F₂[X]/(Xⁿ−1): addition/subtraction is XOR and multiplication is cyclic convolution. Secret low-Hamming-weight vectors x,y and a public random h define s=x+hy. The sender uses fresh sparse r₁,r₂,e to mask an encoded internal message.','HQC 是围绕准循环解码困难问题构造的编码型 KEM。在二进制循环环 F₂[X]/(Xⁿ−1) 中，加减为 XOR，乘法为循环卷积。秘密低汉明重量向量 x、y 与公开随机 h 定义 s=x+hy，发送方用新鲜稀疏 r₁、r₂、e 掩蔽编码后的内部消息。'))
    body+=diagram(lang,'hqc-flow')+math('T = the specified truncation to the codeword length\ns = x + hy\nu = r₁ + hr₂\nv = C(m) + T(sr₂ + e)\nv − T(uy) = C(m) + T(xr₂ + e − r₁y)')
    body+=p(t('Knowing y cancels the large shared term. The residual error can be decoded with the public concatenated code: outer Reed–Solomon encoding, then repeated Reed–Muller encoding; decoding reverses that order. The error-correcting code itself is not secret. Without the secret mask, recovering the appropriate sparse structure or distinguishing the masked relation is tied to the specified quasi-cyclic hard problems.','知道 y 可消去大的公共项，剩余误差由公开级联码纠正：先外层 Reed–Solomon 编码，再重复 Reed–Muller 编码；解码顺序相反。纠错码本身不保密。不知道秘密掩码时，恢复相应稀疏结构或区分掩蔽关系，与规范所述准循环困难问题关联。'),t('The full KEM uses a salted Fujisaki–Okamoto-style transform: derive the PKE coins from the encapsulated message and required context, recover a candidate message, re-encrypt, and select the valid or fallback shared secret. Raw HQC-PKE is not the whole chosen-ciphertext-secure KEM. Decoding-failure probability, constant-time decoding and input validation are critical implementation properties.','完整 KEM 采用加盐的 Fujisaki–Okamoto 类转换：由被封装消息及规定上下文派生 PKE 随机性，恢复候选消息后重加密，再选择有效或回退共享秘密。裸 HQC-PKE 不等于完整的抗选择密文攻击 KEM。解码失败概率、恒定时间解码及输入验证都是关键实现属性。'),t('NIST selected HQC on 11 March 2025 to diversify KEM assumptions beyond lattices. This lesson follows the project specification dated 12 October 2026; its parameters and encodings may differ from older “HQC-128” examples. Selection, project-specification updates and publication of a NIST standard are separate milestones.','NIST 于 2025 年 3 月 11 日选中 HQC，用于增加格以外的 KEM 假设。本节采用项目 2026 年 10 月 12 日版规范，参数和编码可能与较早的 HQC-128 示例不同。被选中、项目规范更新和 NIST 标准发布是三个不同节点。'))+refs(lang,'hqc','hqc-nist','nist')
    out.append(section(lang,'hqc','06',t('HQC: sparse binary masks meet error-correcting codes','HQC：稀疏二进制掩码与纠错码'),body))

    body=p(t('A one-time signature (OTS) authenticates at most one distinct message per key. Winternitz-style schemes encode message-digest digits plus a checksum using positions on one-way hash chains. A signature reveals intermediate chain values; verification hashes forward to recover the public endpoints. Reusing that key for different messages can expose combinations useful for a forgery. The checksum and domain-separated chain functions are essential.','一次性签名（OTS）的每把密钥最多认证一个不同消息。Winternitz 类方案把消息摘要的数字及校验和编码为单向哈希链上的位置；签名揭示中间值，验证沿链向前哈希以恢复公开端点。为不同消息复用密钥可能泄漏可组合伪造的信息。校验和及域分离的链函数不可省略。'))
    body+=diagram(lang,'merkle-path')
    body+=table([t('Construction','构造'),t('OTS + tree mechanism','OTS 与树机制'),t('What the signature contains','签名包含什么')],[['LMS',t('LM-OTS public keys authenticated by an LMS Merkle tree','用 LMS Merkle 树认证 LM-OTS 公钥'),t('Leaf q, LM-OTS signature, algorithm identifiers and authentication path','叶 q、LM-OTS 签名、算法标识及认证路径')],['XMSS',t('WOTS+; address-dependent hashing and L-tree compression of the OTS public key','WOTS+；依地址的哈希及用于压缩 OTS 公钥的 L-tree'),t('Leaf index, randomizer, WOTS+ signature and authentication path','叶索引、随机化值、WOTS+ 签名及认证路径')],['HSS / XMSSᴹᵀ',t('Hierarchies of LMS / XMSS trees authenticate lower-level roots','LMS / XMSS 树层级认证下层根'),t('A chain of authenticated subtrees; finite capacity remains','被认证子树链；容量仍有限')]])
    body+=p(t('For a single height-h Merkle tree, 2ʰ OTS leaves provide at most 2ʰ distinct-message signing slots. The public root stays fixed, but the signer’s next-unused-leaf state changes. Verification derives an OTS public key from the signature and hashes the authentication path to the trusted root; the verifier does not need to track the signer’s next index.','单棵高度 h 的 Merkle 树有 2ʰ 个 OTS 叶，最多提供 2ʰ 个不同消息签名槽位。公开根不变，签名端的下一未用叶状态却不断变化。验证方由签名恢复 OTS 公钥，再沿认证路径哈希至可信根，不需要记录签名端的下一个索引。'))
    body+=diagram(lang,'state-flow')
    body+=p(t('Treat leaf allocation like a security-critical transaction. Concurrent requests, a restored backup, cloned VM or a rolled-back disk can reuse an OTS key. Use the profile’s required hardware/module controls, durable monotonic allocation and a tested exhaustion/rotation plan. A crash may safely burn an index; it must not make that index available again. Distributed signers need explicit non-overlapping allocation and recovery rules.','把叶分配当作安全关键事务。并发请求、恢复备份、克隆虚拟机或磁盘回滚都可能重用 OTS 密钥。应按具体配置要求使用硬件/模块控制、可持久化的单调分配，以及经过测试的耗尽/轮换方案。崩溃可以安全地浪费索引，但不能让它重新可用。分布式签名端还须规定互不重叠的分配和恢复规则。'),t('LMS/XMSS and their multi-tree variants are covered by SP 800-208 under its approved parameter and operational restrictions; RFC 8554 and RFC 8391 describe the constructions. Controlled firmware or release signing is a useful setting to study. They are not a drop-in replacement for every high-concurrency signing service, and are signature schemes rather than KEMs.','SP 800-208 在规定参数及操作限制下覆盖 LMS/XMSS 及其多树变体；RFC 8554 和 RFC 8391 描述构造。可用受控固件或版本签名场景来学习，但不能把它们直接替换进所有高并发签名服务。它们是签名算法，不是 KEM。'))+refs(lang,'208','8554','8391')
    out.append(section(lang,'stateful','07',t('LMS / XMSS: every one-time key needs a one-time allocation','LMS / XMSS：每把一次性密钥都要一次性分配'),body))

    body=p(t('Sizes below are encoded values from the published FIPS documents, not measured speed or a claim of equal security across every row. Private-key seed storage, protocol framing and certificate overhead are separate.','下表为已发布 FIPS 中的编码尺寸，不是实测速度，也不表示每行安全级别相同。私钥种子存储、协议封装及证书开销另计。'))
    body+=table([t('Parameter set','参数组'),t('NIST category','NIST 类别'),t('Public key / bytes','公钥 / 字节'),t('Ciphertext or signature / bytes','密文或签名 / 字节'),t('Task','用途')],[['ML-KEM-768','3','1184','1088',t('KEM ciphertext; 32-byte shared secret','KEM 密文；共享秘密为 32 字节')],['ML-DSA-65','3','1952','3309',t('Signature','签名')],['SLH-DSA-SHA2-128s','1','32','7856',t('Signature','签名')]])
    body+=table([t('Engineering question','工程问题'),t('What to record','需记录什么')],[(t('Assumptions','安全假设'),t('Lattice, code or hash family; parameter set and current analysis','格、编码或哈希路线；参数组及当前分析')),(t('Implementation','实现'),t('Specification/version, encodings, known-answer tests, randomness, side channels and fault behavior','规范版本、编码、已知答案测试、随机数、侧信道与故障行为')),(t('Protocol','协议'),t('Authentication, transcript binding, hybrid combiner, certificate and message-size compatibility','认证、握手上下文绑定、混合组合器、证书与消息尺寸兼容性')),(t('Operational state','运维状态'),t('For LMS/XMSS: atomic allocation, rollback resistance, remaining leaves, backup and rotation','LMS/XMSS：原子分配、防回滚、剩余叶、备份及轮换'))])
    body+=p(t('Algorithm diversity is a way to avoid placing every dependency on one family; it is not proof that any composition is secure. Use the protocol’s specified combiner and actual standardized interfaces. A mathematically correct teaching formula is not a deployment-ready cryptographic implementation.','算法多样性可避免全部依赖同一路线，但不能证明任意组合都安全。应使用协议规定的组合器和真正的标准化接口。教学公式数学上正确，也不等于可部署的密码实现。'))+refs(lang,'203','204','205','208')
    out.append(section(lang,'comparison','08',t('From mechanisms to an implementation review','从机制理解到实现审查'),body))
    return ''.join(out)

def shor_body(lang):
    t=translator(lang)
    body=p(t('Shor reduces integer factorization to finding the multiplicative order r: the smallest positive integer for which aʳ ≡ 1 mod N. First handle easy classical cases, choose a strictly between 1 and N and compute gcd(a,N). A nontrivial gcd already factors N; otherwise a is invertible and the quantum stage can estimate its order. The target is polynomial scaling in the bit length log₂N, not constant-time factoring.','Shor 把整数分解归约为求乘法阶 r：使 aʳ ≡ 1 mod N 的最小正整数。先处理容易的经典情况，再选 1<a<N 并计算 gcd(a,N)；若得到非平凡公因子，已完成分解，否则 a 可逆，进入量子求阶。其目标是相对输入位数 log₂N 的多项式复杂度，不是常数时间分解。'))
    body+=diagram(lang,'shor-flow')
    body+='<h3>'+t('Why a period can reveal factors','为什么阶能揭示因子')+'</h3>'+math('If r is even, let x = a^(r/2) mod N.\nx² − 1 = (x−1)(x+1) ≡ 0 mod N.\nIf x ≠ ±1 mod N, try gcd(x−1,N) and gcd(x+1,N).')
    body+=p(t('For N=15 and a=2, powers repeat as 1,2,4,8,1,…; r=4 gives x=4 and factors gcd(3,15)=3, gcd(5,15)=5. An odd r or a trivial half-power can make this attempt fail; retry with another a. Every output must be checked as a nontrivial factor. ECC is threatened by Shor’s related discrete-logarithm algorithm, not by factoring the elliptic-curve modulus.','N=15、a=2 时，幂依次为 1、2、4、8、1……，r=4 给出 x=4，得到 gcd(3,15)=3、gcd(5,15)=5。奇数阶或平凡半阶幂可能导致本次失败，须更换 a 重试；输出因子必须验证为非平凡因子。ECC 面对的是 Shor 的离散对数算法，不是分解椭圆曲线模数。'))
    body+='<h3>'+t('The quantum part: modular multiplication and phase estimation','量子部分：模乘与相位估计')+'</h3>'+diagram(lang,'shor-circuit')
    body+=math('|0⟩^t |1⟩ → (1/√Q) Σₓ |x⟩ |aˣ mod N⟩,  Q=2ᵗ\nEigenphases of modular multiplication: k/r,  k=0,…,r−1\nAfter inverse QFT and measurement: c/Q ≈ k/r')
    body+=p(t('Hadamards create the counting-register superposition. Controlled powers U^(2^j) compute modular exponentiation coherently; repeated squaring supplies the classical constants for those powers, but the modular arithmetic itself must be implemented reversibly. The work state |1⟩ is a superposition of modular-multiplication eigenstates, whose eigenphases are k/r. Inverse QFT turns this periodic phase structure into peaks in the counting register. It does not read every modular power as a classical list.','Hadamard 门产生计数寄存器叠加；受控 U^(2^j) 相干地完成模幂运算。重复平方可提供各幂的经典常数，但模算术本身须用可逆线路实现。工作态 |1⟩ 是多个模乘本征态的叠加，其本征相位为 k/r。逆 QFT 将这种周期相位结构变成计数寄存器的峰值，并非一次读出所有模幂的经典列表。'),t('Choose enough counting precision, commonly Q of order N² for the textbook reduction. Continued fractions of c/Q produce a candidate denominator. If k and r have a common factor, that denominator may be only a divisor of r; k=0 gives no order information. Check aʳ mod N, combine or repeat samples as appropriate, and then perform the factor test. Peaks are approximate when Q is not divisible by r.','教材归约通常选择 N² 量级的 Q，以提供足够计数精度。对 c/Q 展开连分数可得到候选分母；若 k 与 r 不互素，分母可能只是 r 的因子，k=0 则不提供阶信息。须检查 aʳ mod N，按需组合或重复采样，再执行因子测试。Q 不整除 r 时，峰值是近似分布。'))
    body+='<div class="algorithm-demo" id="shor-demo"><h3>'+t('Inspect four ideal phase samples','检查四个理想相位样本')+'</h3><p>'+t('Fixed example N=15, a=2, t=8, Q=256, true order 4. The chart is an analytic ideal distribution; the buttons perform only classical postprocessing.','固定例子 N=15、a=2、t=8、Q=256，真实阶为 4。图为解析理想分布，按钮只执行经典后处理。')+'</p><div class="phase-peaks">'+''.join(f'<div><span class="peak-bar" style="height:90px"></span><b>c={c}</b><small>P=25%</small></div>' for c in (0,64,128,192))+'</div><div class="demo-buttons" role="group" aria-label="'+t('Choose phase sample','选择相位样本')+'">'+''.join(f'<button type="button" data-shor-sample="{c}" aria-pressed="{str(c==64).lower()}">c = {c}</button>' for c in (0,64,128,192))+'</div><output id="shor-result" aria-live="polite">'+t('c=64: 64/256=1/4 → r=4 → factors 3 and 5.','c=64：64/256=1/4 → r=4 → 因子 3 和 5。')+'</output></div>'
    body+='<h3>'+t('Why elliptic-curve keys are also affected','为什么椭圆曲线密钥同样受影响')+'</h3>'
    body+=p(t('For a prime-order group with generator P and public point Q=dP, the discrete-logarithm version coherently evaluates aP+bQ, with a,b taken modulo the group order ℓ. Inputs shifted by (−dt,t) produce the same group element. Fourier sampling extracts a relation between two measured frequencies, rather than factoring a field modulus.','对于生成元 P、公开点 Q=dP 的素数阶群，离散对数版本对模群阶 ℓ 的 a、b 相干计算 aP+bQ。输入平移 (−dt,t) 后群元素不变；傅里叶采样提取两个测量频率间的关系，而不是分解有限域模数。'))
    body+=math('Q = dP;  f(a,b) = aP + bQ = (a+bd)P\nFourier samples (u,v) satisfy v = d·u (mod ℓ).\nFor u ≠ 0 in this prime-order group: d = v·u⁻¹ mod ℓ.')
    body+=p(t('This is a conceptual hidden-subgroup view: reversible group arithmetic, suitable registers and Fourier operations still have to be implemented. Finite-field Diffie–Hellman has an analogous discrete-logarithm formulation.','这是隐藏子群的概念视图；仍需实现可逆群算术、适当寄存器及傅里叶运算。有限域 Diffie–Hellman 也有相应的离散对数形式。'))
    body+=p(t('A cryptographically relevant attack also needs fault-tolerant logical qubits, reversible modular arithmetic, error correction and a large gate budget. This worked example is not a circuit execution, benchmark, or evidence that present hardware can factor RSA keys.','密码学规模攻击还需要容错逻辑量子位、可逆模算术、纠错及庞大门预算。这个例子不是线路执行或性能测试，也不能证明当前硬件已能分解 RSA 密钥。'))+refs(lang,'shor')
    return section(lang,'shor','03',t('Shor: from modular periods to factors','Shor：从模运算周期到因子'),body)

def grover_body(lang):
    t=translator(lang)
    body=p(t('Grover searches N candidates using a reversible predicate f(x) that marks M acceptable solutions. Preparing an address superposition does not make a classical database freely quantum-accessible: the predicate, data access and reversible computation all count. The quantum advantage is O(√(N/M)) oracle queries under the specified model, rather than the classical O(N/M) search cost.','Grover 用可逆判定函数 f(x) 在 N 个候选中标记 M 个可接受解。地址叠加并不会让经典数据库自动具备免费量子访问能力；判定、数据访问和可逆计算都计入成本。它在规定模型下提供 O(√(N/M)) 次 Oracle 查询，相对于经典 O(N/M) 搜索有平方根优势。'))
    body+=diagram(lang,'grover-flow')+math('U_f|x⟩|b⟩ = |x⟩|b ⊕ f(x)⟩\nWith |b⟩ = |−⟩, phase kickback gives O_f|x⟩ = (−1)^f(x)|x⟩.\nD = 2|s⟩⟨s| − I;  each amplitude αₓ becomes 2·mean(α) − αₓ.')
    body+=p(t('The oracle can test a candidate without knowing the solution in advance. For key search, a reversible cipher computes a known plaintext/ciphertext check, phase-marks matching keys, then uncomputes temporary work registers. Multiple pairs may be needed to identify the intended key. A hand-written oracle that simply marks a known answer illustrates interference but does not implement this cryptanalytic workload.','Oracle 无需预先知道解，也可以检查候选。密钥搜索中，可逆密码线路检验已知明密文对，给匹配密钥施加相位，再反计算清理临时寄存器；有时需要多组明密文对排除其他匹配密钥。直接标记已知答案的教学 Oracle 只演示干涉，没有实现完整密码分析工作负载。'))
    body+='<h3>'+t('One complete iteration, with four candidates','四候选的一次完整迭代')+'</h3>'+table([t('Stage','阶段'),t('Target amplitude','目标振幅'),t('Each other amplitude','其余每项振幅'),t('Target measurement probability','目标测量概率')],[[t('Uniform state','均匀态'),'1/2','1/2','1/4'],[t('Oracle only','仅 Oracle'),'−1/2','1/2','1/4'],[t('After diffusion; mean=1/4','扩散后；反射前均值=1/4'),'1','0','1']])
    body+=math('|s⟩ = sin θ |good⟩ + cos θ |bad⟩,  sin²θ = M/N\nG = D·O_f rotates by 2θ in this two-dimensional subspace.\nAfter k iterations: P(success) = sin²((2k+1)θ).\nFirst peak near k ≈ π/(4θ) − 1/2; choose an appropriate nearby integer.')
    body+=p(t('For one marked item among four, θ=π/6 and one iteration gives success probability 1 in the ideal model. For larger N the optimum is usually near, rather than exactly at, probability 1. Repeating beyond the peak rotates away from the good subspace. If M is unknown, estimating it or using an adaptive search schedule is a separate part of the algorithm.','四个候选中只有一个目标时，θ=π/6，一次迭代在理想模型下成功率为 1。更大 N 的最优整数迭代通常只能接近 1；越过峰值继续重复，会转离目标子空间。M 未知时，估计目标数或采用自适应搜索安排是另一项算法步骤。'))
    body+='''<div class="algorithm-demo" id="grover-demo"><h3>'''+t('Watch the probability rise, peak and fall','观察成功率上升、见顶与下降')+'''</h3><p>'''+t('Exact real-amplitude simulation on this device; one marked state x=0. It does not simulate a cipher oracle, hardware noise or error correction.','本机精确实振幅模拟，唯一标记态为 x=0；不模拟密码 Oracle、硬件噪声或纠错。')+'''</p><div class="demo-controls"><label for="grover-size">'''+t('Candidates N','候选数 N')+'''</label><select id="grover-size"><option value="4">4</option><option value="16">16</option><option value="64">64</option></select><label for="grover-iterations">'''+t('Full iterations k','完整迭代数 k')+'''</label><input id="grover-iterations" type="range" min="0" max="12" value="1"><output id="grover-k">1</output><button type="button" id="grover-optimum">'''+t('Near first peak','跳至首个峰值附近')+'''</button></div><label class="oracle-toggle"><input type="checkbox" id="grover-oracle">'''+t('Apply one extra phase oracle (probabilities stay the same)','额外施加一次相位 Oracle（概率不变）')+'''</label><div class="grover-stats" id="grover-summary" aria-live="polite"></div><div id="grover-amplitudes" class="amplitude-table"></div><div class="diagram-scroll" tabindex="0"><svg id="grover-curve" class="wide-diagram" viewBox="0 0 780 235" role="img" aria-label="'''+t('Target success probability against iteration count','目标成功率随迭代数变化')+'''"></svg></div><p class="demo-note">'''+t('The curve shows complete iterations. Toggling an extra oracle changes a sign, not the point on the probability curve.','曲线表示完整迭代。额外 Oracle 只改变符号，不改变概率曲线上的点。')+'''</p></div>'''
    body+='<h3>'+t('What this means for cryptography','对密码学意味着什么')+'</h3>'+p(t('An ideal unique-solution search of a b-bit key has N=2ᵇ and roughly 2^(b/2) query scaling. That is not a wall-clock prediction or a complete security estimate: oracle gate count, circuit depth, quantum memory, parallelization and fault tolerance matter. Generic n-bit hash preimage search fits this model; collision finding is a different task with different algorithms and trade-offs. Do not apply “halve the bits” to every hash property.','理想的 b 位密钥唯一解搜索有 N=2ᵇ，查询量约按 2^(b/2) 缩放。这不是实际耗时预测或完整安全估计，还须考虑 Oracle 门数、线路深度、量子存储、并行化与容错成本。一般 n 位哈希原像搜索适用此模型，碰撞搜索则是不同任务，有不同算法及取舍，不能把“位数减半”套到全部哈希性质。'),t('Shor exploits algebraic structure to threaten factoring/discrete-log public-key systems. Grover provides a generic quadratic search improvement. Neither result, by itself, says that a particular deployed system has been broken.','Shor 利用代数结构威胁整数分解/离散对数公钥系统；Grover 提供一般搜索的平方加速。二者都不能单独证明某个已部署系统已经被攻破。'))+refs(lang,'grover','search')
    return section(lang,'grover','04',t('Grover: phase marking becomes amplitude amplification','Grover：从相位标记到振幅放大'),body)
